      "search": "SELECT i.id,i.project_id,i.number,i.title,i.description,i.priority,i.state,i.assignee_id,i.version,i.archived FROM issues_search s JOIN issues_issues i ON i.rowid=s.rowid WHERE issues_search MATCH ? AND s.workspace_id=? AND s.project_id=? AND s.archived='0' AND i.workspace_id=? AND i.project_id=? AND i.archived=0 ORDER BY bm25(issues_search),i.number DESC LIMIT ?",
      "searchShort": "WITH terms(pattern) AS (VALUES (?),(?),(?),(?),(?),(?),(?),(?),(?),(?),(?),(?)) SELECT i.id,i.project_id,i.number,i.title,i.description,i.priority,i.state,i.assignee_id,i.version,i.archived FROM issues_issues i WHERE i.workspace_id=? AND i.project_id=? AND i.archived=0 AND NOT EXISTS (SELECT 1 FROM terms WHERE pattern IS NOT NULL AND NOT (i.title LIKE pattern ESCAPE '\\' OR i.description LIKE pattern ESCAPE '\\')) ORDER BY i.number DESC LIMIT ?",
